<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class Content {
 public static function create(\PDO $p,int $u,string $module,int $org,array $d):int {Core::module($p,$module);if(!Authorization::super($p,$u))Authorization::require($p,$u,$module.'.content.manage',$org);if(!in_array($d['type']??'',['BANNER','ACTIVITY','GALLERY','ANNOUNCEMENT'],true))throw new \RuntimeException('Content type tidak sah.');$starts=\EPejabat\Modules\Training\Workflow::date($d['starts_at']??'');$ends=\EPejabat\Modules\Training\Workflow::date($d['ends_at']??'');if($starts>=$ends)throw new \RuntimeException('Publish window tidak sah.');$url=Core::text($d['cta_url']??'',500,false);if($url!==''&&(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https'||parse_url($url,PHP_URL_USER)!==null||parse_url($url,PHP_URL_PASS)!==null))throw new \RuntimeException('CTA mesti HTTPS.');$doc=Core::id($d['document_id']??null,true);$version=$doc?Core::id($d['document_version']??''):null;if($doc){$v=Documents::version($p,$u,$doc,$version);$meta=Documents::access($p,$u,$doc,true);if((int)$meta['organisation_id']!==$org||$meta['module_code']!==$module||!in_array($v['mime'],['image/jpeg','image/png'],true)||Database::query($p,'SELECT 1 FROM core_signatories WHERE signature_document_id=?',[$doc])->fetchColumn())throw new \RuntimeException('Public image scope/type tidak sah.');}$order=filter_var($d['sort_order']??0,FILTER_VALIDATE_INT);if($order===false)throw new \RuntimeException('Order tidak sah.');Database::query($p,'INSERT INTO core_content(module_code,organisation_id,type_key,title,body,cta_url,document_id,document_version,starts_at,ends_at,sort_order,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$module,$org,$d['type'],Core::text($d['title']??''),Core::text($d['body']??'',10000,false),$url,$doc,$version,$starts,$ends,$order,$u]);$id=(int)$p->lastInsertId();Audit::record($p,'content.created',$u,$org,(string)$id,$module);return $id;}
 public static function publish(\PDO $p,int $u,int $id,bool $active):void {$r=Database::query($p,'SELECT * FROM core_content WHERE id=?',[$id])->fetch();if(!$r)throw new \RuntimeException('Content tidak wujud.');Core::module($p,$r['module_code']);if(!Authorization::super($p,$u))Authorization::require($p,$u,$r['module_code'].'.content.manage',(int)$r['organisation_id']);Database::query($p,'UPDATE core_content SET status=? WHERE id=?',[$active?'PUBLISHED':'UNPUBLISHED',$id]);Audit::record($p,'content.publication_changed',$u,(int)$r['organisation_id'],(string)$id,$r['module_code'],null,null,['published'=>$active]);}
 public static function publicRows(\PDO $p,string $module):array {Core::module($p,$module);return Database::query($p,"SELECT c.id,c.type_key,c.title,c.body,c.cta_url,c.document_id,c.document_version,c.sort_order FROM core_content c JOIN organisations o ON o.id=c.organisation_id WHERE c.module_code=? AND c.status='PUBLISHED' AND c.starts_at<=UTC_TIMESTAMP() AND c.ends_at>=UTC_TIMESTAMP() AND o.is_active=1 ORDER BY c.sort_order,c.id",[$module])->fetchAll();}
 public static function asset(\PDO $p,int $id,string $module):array {Core::module($p,$module);$row=Database::query($p,"SELECT c.*,v.storage_key,v.mime,v.checksum FROM core_content c JOIN document_versions v ON v.document_id=c.document_id AND v.version=c.document_version JOIN organisations o ON o.id=c.organisation_id WHERE c.id=? AND c.module_code=? AND c.status='PUBLISHED' AND c.starts_at<=UTC_TIMESTAMP() AND c.ends_at>=UTC_TIMESTAMP() AND o.is_active=1",[$id,$module])->fetch();if(!$row||!in_array($row['mime'],['image/jpeg','image/png'],true)||!preg_match('/\A[a-f0-9]{64}\z/',$row['storage_key'])||Database::query($p,'SELECT 1 FROM core_signatories WHERE signature_document_id=?',[$row['document_id']])->fetchColumn())throw new \RuntimeException('Imej public tidak tersedia.');$path=APP_ROOT.'/storage/documents/'.$row['storage_key'];if(!is_file($path)||!hash_equals($row['checksum'],hash_file('sha256',$path)))throw new \RuntimeException('Image integrity gagal.');return ['path'=>$path,'mime'=>$row['mime']];}
}
